import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"What is handl?","description":"","frontmatter":{},"headers":[],"relativePath":"handl/explanation/what-is-handl.md","filePath":"vendored/handl/explanation/what-is-handl.md"}`),a={name:`handl/explanation/what-is-handl.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="what-is-handl" tabindex="-1">What is handl? <a class="header-anchor" href="#what-is-handl" aria-label="Permalink to “What is handl?”">​</a></h1><p>handl is a <strong>platform for building languages</strong> — a closed arrow-calculus kernel, a data-driven engine layer, and a composable plugin host.</p><p>The published pieces today are the machinery, not the language. The handl surface language (its syntax, its standard library, and the <code>hnl</code> toolchain) is still in development and is deliberately not documented here.</p><h2 id="three-ideas-one-stack" tabindex="-1">Three ideas, one stack <a class="header-anchor" href="#three-ideas-one-stack" aria-label="Permalink to “Three ideas, one stack”">​</a></h2><p><strong>The kernel is a closed arrow calculus.</strong> All computation is an arrow <code>A ~&gt; B</code> built from six combinators — <code>arr</code>, <code>&gt;&gt;&gt;</code>, <code>first</code>, <code>choice</code>, <code>loop</code>, <code>app</code>. Everything is an object in one world (<code>Obj : sym()</code>); types, grades, proofs, and capabilities are ordinary objects, and there is no separate lambda, closure, or mutable-environment machinery. See <a href="./arrow-calculus-kernel.html">The arrow calculus kernel</a> and <a href="https://github.com/handl-lang/host/blob/project/adrs/0106-object-arrow-kernel.md" target="_blank" rel="noreferrer">ADR-0106</a>.</p><p><strong>A language is data.</strong> A <code>Language</code> value is assembled from YAML fragments — tokens, grammar, eval schemes, types, AST shapes. Engines for lexing, parsing, transforming, and executing are generic: they dispatch on the <code>Language</code> data, never on hardcoded constructs. A new language is a data change, not an engine recompile. See <a href="./language-as-data.html">Language as data</a>.</p><p><strong>The host is a composer.</strong> An empty <code>Host</code> loads <code>Plugin</code>s, resolves their dependencies, runs <code>contribute</code> to a fixed point, and dispatches capabilities. A parser is a <code>RuleAcceptor</code> for <code>Behavior&lt;Parser&gt;</code>; a formatter accepts <code>Behavior&lt;Format&gt;</code>; a target contributes evaluation or compilation rules. The host does not know which tool it becomes. See <a href="./composable-host.html">The composable host</a>.</p><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to “Why this matters”">​</a></h2><ul><li><strong>Composability over feature flags.</strong> You do not enable a feature in a central compiler — you load the plugin that provides it, and leave out the ones you do not need.</li><li><strong>Host-defined capabilities.</strong> I/O and platform services live in modules contributed by library and target plugins, so the same program can run against a real OS backend, an in-memory stub, or a browser implementation depending on the host.</li><li><strong>A small, honest core.</strong> Because the calculus is closed and the language is data, every consumer — interpreter, typechecker, pretty-printer, serializer — covers a fixed, tiny vocabulary.</li></ul><h2 id="where-the-platform-fits" tabindex="-1">Where the platform fits <a class="header-anchor" href="#where-the-platform-fits" aria-label="Permalink to “Where the platform fits”">​</a></h2><p>The platform is a good fit for:</p><ul><li>Building an embeddable expression language inside a larger application.</li><li>Assembling DSLs and language variants from shared machinery without forking a compiler.</li><li>Tools that must agree on one language definition — a formatter, a linter, an LSP server, and an interpreter can all consume the same <code>Language</code> data.</li></ul><p>It is not a general-purpose systems language. It deliberately leaves I/O, concurrency, and platform details to the host, so the same machinery can be shaped into many different tools.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};